from pathlib import Path
import subprocess,zipfile,xml.etree.ElementTree as E,csv,io
root=Path(__file__).resolve().parent.parent
out=root/'evidence'
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
for p in root.glob('*.pdf'):
    subprocess.run(['pdftotext','-layout',str(p),str(out/(p.stem+'.txt'))],check=True)
for p in root.glob('*.xlsx'):
    with zipfile.ZipFile(p) as z:
        ss=[]
        if 'xl/sharedStrings.xml' in z.namelist():
            ss=[''.join(si.itertext()) for si in E.fromstring(z.read('xl/sharedStrings.xml'))]
        lines=[]
        for name in z.namelist():
            if name.startswith('xl/worksheets/sheet') and name.endswith('.xml'):
                lines.append('SHEET '+name)
                for row in E.fromstring(z.read(name)).findall('.//m:row',ns):
                    cells=[]
                    for c in row.findall('m:c',ns):
                        v=c.find('m:v',ns)
                        value=v.text if v is not None else ''.join(c.find('m:is',ns).itertext()) if c.find('m:is',ns) is not None else ''
                        if c.get('t')=='s' and value: value=ss[int(value)]
                        if value: cells.append(c.get('r')+'='+value)
                    if cells: lines.append(' | '.join(cells))
        (out/(p.stem+'.txt')).write_text('\\n'.join(lines)+'\\n')
for p in root.glob('*.csv'):
    raw=p.read_bytes()
    for enc in ['utf-8-sig','cp932','utf-16']:
        try: s=raw.decode(enc);break
        except UnicodeError: pass
    (out/(p.stem+'_csv.txt')).write_text('ENCODING '+enc+'\\n'+s)
# PDF page index for locating evidence. Physical pages are 1-based.
lines=[]
for p in sorted(root.glob('*.pdf')):
    pages=(out/(p.stem+'.txt')).read_text().split('\\f')
    for i,page in enumerate(pages,1):
        hits=[x.strip() for x in page.splitlines() if any(k in ''.join(x.split()) for k in ['ストーカー事案の検挙状況','基準年中','凡例','被疑者と被害者との関係','解決事件','主たる被疑者'])]
        if hits: lines.append(f'{p.name} PDF p.{i}: '+' / '.join(hits))
(out/'page_index.txt').write_text('\\n'.join(lines)+'\\n')
